    try {
      const outsideFile = join(outside, "secret.txt");
      writeFileSync(outsideFile, "secret\n", "utf8");

      const editPreview = buildPendingEditPreviewData(
        { path: outsideFile, oldText: "secret", newText: "safe" },
        workspace,
