	return {
		name,
		description: `Built-in ${name} tool`,
		parameters: {},
		execute: () => {},
	};
}

function withTempDir(name: string, fn: (dir: string) => void): void {
	const dir = mkdtempSync(join(tmpdir(), name));
	try {
		fn(dir);
	} finally {
		rmSync(dir, { recursive: true, force: true });
	}
}

