import assert from "node:assert/strict";
import test from "node:test";
import { registerThinkingLabeling } from "../src/thinking-label.ts";

type Handler = (event: unknown, ctx?: unknown) => Promise<void> | void;
type Transformer = (markdown: string, context: { messageType: string }) => string;

const theme = { fg: (color: string, text: string) => `<${color}>${text}</${color}>` };

function register(): { handlers: Map<string, Handler[]>; transformers: Transformer[] } {
  const handlers = new Map<string, Handler[]>();
  const transformers: Transformer[] = [];
  registerThinkingLabeling({
    on(eventName: string, handler: Handler): void {
      handlers.set(eventName, [...(handlers.get(eventName) ?? []), handler]);
    },
    registerMarkdownTransformer(transformer: Transformer): void {
      transformers.push(transformer);
    },
  } as never);
  return { handlers, transformers };
}

async function emit(handlers: Map<string, Handler[]>, eventName: string, event: unknown, ctx?: unknown): Promise<void> {
  for (const handler of handlers.get(eventName) ?? []) await handler(event, ctx);
}

test("a finished assistant message keeps its thinking exactly as the provider returned it", async () => {
  const { handlers } = register();
  const thinking = "Checking the log for the cause.\n\n";
  const message = {
    role: "assistant",
    api: "anthropic-messages",
    content: [{ type: "thinking", thinking, thinkingSignature: "sig" }, { type: "text", text: "Done." }],
  };
  const before = structuredClone(message);

  await emit(handlers, "message_update", { message }, { ui: { theme } });
  await emit(handlers, "message_end", { message }, { ui: { theme } });

  assert.deepEqual(message, before);
});

