    transform!("checking options", { messageType: "assistant-thinking" }),
    "<accent>Thinking:</accent> checking options",
  );
  assert.equal(transform!("plain reply", { messageType: "assistant" }), "plain reply");
  assert.equal(transform!("my prompt", { messageType: "user" }), "my prompt");
});

